// Code node: "Price the Proposal" (Run Once for All Items)
const COMPANY = 'RixDigi';
const PREPARED_BY = 'Aqib ur Rehman';
const VALID_DAYS = 14;

// Service catalogue (matches the Upwork project catalogue)
const SERVICES = {
  'Self-Hosted n8n Setup & Server Optimisation': {
    Starter: { price: 100, days: 2, scope: ['n8n on Ubuntu VPS with Docker Compose', 'PostgreSQL database and Caddy SSL', 'Webhook and credential testing'] },
    Standard: { price: 250, days: 4, scope: ['Everything in Starter', '2 API/CRM integration workflows', 'Error-notification alerts'] },
    Advanced: { price: 500, days: 7, scope: ['Everything in Standard', 'Redis queue mode with workers', 'Automated backups and restore runbook'] },
  },
  'Custom AI Agent with Tool Calling': {
    Starter: { price: 150, days: 2, scope: ['AI agent with 1 external API tool', 'Custom system prompt and guardrails', 'Deployment to one channel'] },
    Standard: { price: 350, days: 4, scope: ['Multi-step agent with persistent memory', 'CRM lookup tool', 'Email/Slack alerts'] },
    Advanced: { price: 700, days: 7, scope: ['Multi-agent orchestration', 'Human-in-the-loop approvals', 'Custom API tool integrations'] },
  },
  'RAG Knowledge Base with Vector Search': {
    Starter: { price: 200, days: 3, scope: ['Ingest up to 25 documents', 'Vector index (Qdrant/pgvector)', 'Basic Q&A workflow with citations'] },
    Standard: { price: 450, days: 5, scope: ['Hybrid search with re-ranking', 'Automated Drive/Notion sync', 'Source citations in every answer'] },
    Advanced: { price: 900, days: 7, scope: ['Multi-source ingestion', 'Role-based access control', 'Slack/Teams and web chat UI'] },
  },
  'PDF & Invoice Data Extraction Pipeline': {
    Starter: { price: 120, days: 2, scope: ['1 document type', 'Structured extraction to Google Sheets/Airtable', 'Validation rules'] },
    Standard: { price: 300, days: 4, scope: ['Multi-page PDFs and nested tables', 'Sync to your CRM/database', 'Duplicate detection'] },
    Advanced: { price: 600, days: 7, scope: ['Email-triggered ingestion', 'Xero/ERP sync', 'Human review queue'] },
  },
  'AI Voice Agent (Retell AI / Vapi)': {
    Starter: { price: 250, days: 3, scope: ['1 inbound voice agent', 'Custom call script and FAQs', 'Phone number connection'] },
    Standard: { price: 500, days: 5, scope: ['Live calendar booking', 'CRM sync', 'SMS follow-ups'] },
    Advanced: { price: 950, days: 8, scope: ['Database lookups during calls', 'Live call transfer', 'Custom webhooks'] },
  },
};
const ADDONS = {
  '30-day priority support (+$99)': { price: 99, days: 0 },
  'Extra integration or workflow (+$75)': { price: 75, days: 2 },
  'Team training session, 1 hour (+$60)': { price: 60, days: 0 },
  'Technical documentation pack (+$80)': { price: 80, days: 1 },
};
const RUSH = 'Rush delivery (+25%, about 40% faster)';

const toList = (v) => (Array.isArray(v) ? v : v ? String(v).split(',').map((s) => s.trim()).filter(Boolean) : []);
const token = () => Array.from({ length: 4 }, () => Math.random().toString(36).slice(2, 8)).join('');
const addDays = (n) => new Date(Date.now() + n * 864e5).toISOString().slice(0, 10);

const out = [];
for (const item of $input.all()) {
  const f = item.json;
  const serviceName = f['Service'] in SERVICES ? f['Service'] : Object.keys(SERVICES)[0];
  const tierName = ['Starter', 'Standard', 'Advanced'].includes(f['Package']) ? f['Package'] : 'Standard';
  const tier = SERVICES[serviceName][tierName];
  const extras = toList(f['Add-ons']);

  const lines = [{ description: `${serviceName} — ${tierName} package`, detail: tier.scope.join(' · '), amount: tier.price }];
  let days = tier.days;
  for (const a of extras) {
    if (ADDONS[a]) {
      lines.push({ description: a.replace(/\s*\(\+\$\d+\)$/, ''), detail: '', amount: ADDONS[a].price });
      days += ADDONS[a].days;
    }
  }
  let subtotal = lines.reduce((s, l) => s + l.amount, 0);
  if (extras.includes(RUSH)) {
    const rush = Math.round(subtotal * 0.25);
    lines.push({ description: 'Rush delivery', detail: 'Priority scheduling', amount: rush });
    subtotal += rush;
    days = Math.max(1, Math.ceil(days * 0.6));
  }
  const discountPct = Math.min(30, Math.max(0, Number(f['Discount %']) || 0));
  const discount = Math.round((subtotal * discountPct) / 100);
  const total = subtotal - discount;

  const now = new Date();
  const number = `Q-${now.toISOString().slice(0, 10).replace(/-/g, '')}-${Math.floor(Math.random() * 9000 + 1000)}`;
  out.push({
    json: {
      token: token(),
      number,
      createdAt: now.toISOString(),
      validUntil: addDays(VALID_DAYS),
      company: COMPANY,
      preparedBy: PREPARED_BY,
      client: {
        name: String(f['Client Name'] || '').trim(),
        email: String(f['Client Email'] || '').trim(),
        company: String(f['Client Company'] || '').trim(),
      },
      title: String(f['Project Title'] || serviceName).trim(),
      service: serviceName,
      package: tierName,
      scope: tier.scope,
      lines,
      subtotal,
      discountPct,
      discount,
      total,
      deliveryDays: days,
      notes: String(f['Notes for the client'] || '').trim(),
      paymentTerms: '50% to start, 50% on delivery. Paid via Upwork milestones or bank transfer.',
    },
  });
}
return out;

// Code node: "Save Proposal" (Run Once for All Items)
const store = $getWorkflowStaticData('global');
store.quotes = store.quotes || {};
store.order = store.order || [];
for (const item of $input.all()) {
  store.quotes[item.json.token] = item.json;
  store.order.unshift(item.json.token);
}
// keep the latest 300 proposals
for (const t of store.order.slice(300)) delete store.quotes[t];
store.order = store.order.slice(0, 300);
return $input.all();

// Code node: "Render Proposal" (Run Once for All Items)
const store = $getWorkflowStaticData('global');
const q = $input.first().json.query || {};
const p = (store.quotes || {})[String(q.t || '')];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n) => '$' + Number(n).toLocaleString('en-US');
const fmt = (iso) => new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });

let inner;
if (!p) {
  inner = '<div class="sheet"><h1>Proposal not found</h1><p class="muted">This link is invalid or the proposal has expired.</p></div>';
} else {
  const rows = p.lines
    .map((l) => `<tr><td><strong>${esc(l.description)}</strong>${l.detail ? `<div class="muted">${esc(l.detail)}</div>` : ''}</td><td class="num">${money(l.amount)}</td></tr>`)
    .join('');
  inner = `<div class="toolbar"><button onclick="window.print()">Print / Save as PDF</button></div>
<article class="sheet">
<header class="top"><div><div class="brand">${esc(p.company)}</div><div class="muted">AI Agents · Automation · Voice AI</div></div>
<div class="meta"><div><span>Proposal</span><b>${esc(p.number)}</b></div><div><span>Date</span><b>${esc(fmt(p.createdAt))}</b></div><div><span>Valid until</span><b>${esc(fmt(p.validUntil))}</b></div></div></header>
<section class="parties"><div><span class="label">Prepared for</span><b>${esc(p.client.name)}</b>${p.client.company ? `<div>${esc(p.client.company)}</div>` : ''}<div class="muted">${esc(p.client.email)}</div></div>
<div><span class="label">Prepared by</span><b>${esc(p.preparedBy)}</b><div>${esc(p.company)}</div></div></section>
<h1>${esc(p.title)}</h1>
<h2>Scope of work</h2>
<ul>${p.scope.map((s) => `<li>${esc(s)}</li>`).join('')}</ul>
<h2>Investment</h2>
<table><thead><tr><th>Item</th><th class="num">Amount</th></tr></thead><tbody>${rows}</tbody>
<tfoot><tr><td>Subtotal</td><td class="num">${money(p.subtotal)}</td></tr>
${p.discount ? `<tr><td>Discount (${p.discountPct}%)</td><td class="num">−${money(p.discount)}</td></tr>` : ''}
<tr class="total"><td>Total</td><td class="num">${money(p.total)}</td></tr></tfoot></table>
<section class="grid"><div><span class="label">Estimated delivery</span><b>${p.deliveryDays} working days</b></div><div><span class="label">Payment terms</span><b>${esc(p.paymentTerms)}</b></div></section>
${p.notes ? `<h2>Notes</h2><p>${esc(p.notes).replace(/\n/g, '<br>')}</p>` : ''}
<h2>Next steps</h2>
<ol><li>Reply to confirm the scope, or tell us what to adjust.</li><li>We set up the first milestone and schedule a kickoff call.</li><li>You get progress updates at every step until handover.</li></ol>
<footer class="muted">This proposal was generated automatically from our service catalogue and is valid until ${esc(fmt(p.validUntil))}.</footer>
</article>`;
}

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${p ? esc(p.number + ' · ' + p.title) : 'Proposal'}</title>
<style>
:root{--ink:#16181d;--muted:#6b7280;--line:#e5e7eb;--accent:#4f46e5;--bg:#eef0f4}
*{box-sizing:border-box}body{margin:0;font:14px/1.55 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
.toolbar{max-width:820px;margin:20px auto 0;padding:0 16px;text-align:right}
button{background:var(--accent);color:#fff;border:0;border-radius:8px;padding:9px 16px;font-weight:600;cursor:pointer}
.sheet{max-width:820px;margin:12px auto 32px;background:#fff;padding:44px 48px;border-radius:12px;box-shadow:0 4px 24px rgba(0,0,0,.06)}
@media(max-width:640px){.sheet{padding:24px 18px}}
.top{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;border-bottom:3px solid var(--accent);padding-bottom:18px}
.brand{font-size:24px;font-weight:800;color:var(--accent);letter-spacing:-.02em}
.meta{display:flex;gap:22px;flex-wrap:wrap}.meta span,.label{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}
.parties{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:22px 0}@media(max-width:640px){.parties{grid-template-columns:1fr}}
h1{font-size:22px;margin:8px 0 4px}h2{font-size:14px;text-transform:uppercase;letter-spacing:.06em;color:var(--accent);margin:26px 0 8px}
ul,ol{margin:0;padding-left:20px}li{margin:3px 0}.muted{color:var(--muted);font-size:12px}
table{width:100%;border-collapse:collapse}th,td{padding:10px 0;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.num{text-align:right;white-space:nowrap}
tfoot td{border:0;padding:6px 0}tfoot .total td{font-size:18px;font-weight:800;border-top:2px solid var(--ink);padding-top:10px}
.grid{display:grid;grid-template-columns:1fr 2fr;gap:18px;margin-top:22px}@media(max-width:640px){.grid{grid-template-columns:1fr}}
footer{margin-top:30px;border-top:1px solid var(--line);padding-top:12px}
@media print{body{background:#fff}.toolbar{display:none}.sheet{box-shadow:none;margin:0;max-width:none;padding:0}@page{size:A4;margin:18mm}}
</style></head><body>${inner}</body></html>`;
return [{ json: { html, found: !!p } }];
